  auto CENTER_NAME__ = CENTER_NAME ? _fbb.CreateString(CENTER_NAME) : 0;
  auto TRAJ_REF_FRAME__ = TRAJ_REF_FRAME ? _fbb.CreateString(TRAJ_REF_FRAME) : 0;
